@dataclass
class PluginRuntime:
    shutdown_event: threading.Event = field(default_factory=threading.Event)
    started_at: float = field(default_factory=time.time)
    generation: int = 0
    config_revision: int = 0
    mapping_revision: int = 0
    lock: threading.RLock = field(default_factory=threading.RLock)

    def restart(self) -> None:
        with self.lock:
            self.shutdown_event.clear()
            self.started_at = time.time()
            self.generation += 1

    def stop(self) -> None:
        self.shutdown_event.set()

    def mark_config_changed(self) -> None:
        with self.lock:
            self.config_revision += 1

    def mark_mappings_changed(self) -> None:
        with self.lock:
            self.mapping_revision += 1

    def snapshot(self) -> Dict[str, object]:
        with self.lock:
            return {
                "generation": self.generation,
                "started_at": self.started_at,
                "config_revision": self.config_revision,
                "mapping_revision": self.mapping_revision,
                "shutting_down": self.shutdown_event.is_set(),
            }


class SQLiteThreadState(threading.local):
    def __init__(self) -> None:
        self.connection: Optional[sqlite3.Connection] = None
        self.path: Optional[str] = None
        self.generation = -1


class SQLiteRuntime:
    def __init__(self) -> None:
        self._local = SQLiteThreadState()
        self._lock = threading.RLock()
        self._connections: Dict[int, sqlite3.Connection] = {}
        self._generation = 0

    def connect(self, path: str) -> sqlite3.Connection:
        connection = self._local.connection
        local_path = self._local.path
        local_generation = self._local.generation
        if (
            connection is not None
            and local_path == path
            and local_generation == self._generation
        ):
            return connection
        self.close_current()
        os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
        connection = sqlite3.connect(
            path,
            timeout=30,
            isolation_level=None,
            check_same_thread=False,
        )
        connection.row_factory = sqlite3.Row
        connection.execute("PRAGMA journal_mode = WAL")
        connection.execute("PRAGMA synchronous = NORMAL")
        connection.execute("PRAGMA foreign_keys = ON")
        connection.execute("PRAGMA busy_timeout = 30000")
        connection.execute("PRAGMA temp_store = MEMORY")
        with self._lock:
            self._connections[id(connection)] = connection
            generation = self._generation
        self._local.connection = connection
        self._local.path = path
        self._local.generation = generation
        return connection

    def close_current(self) -> None:
        connection = self._local.connection
        if connection is None:
            return
        with self._lock:
            self._connections.pop(id(connection), None)
        try:
            connection.close()
        except Exception:
            pass
        self._local.connection = None
        self._local.path = None
        self._local.generation = -1

    def close_all(self) -> None:
        with self._lock:
            connections = list(self._connections.values())
            self._connections.clear()
            self._generation += 1
        for connection in connections:
            try:
                connection.execute("PRAGMA optimize")
            except Exception:
                pass
            try:
                connection.close()
            except Exception:
                pass
        self._local.connection = None
        self._local.path = None
        self._local.generation = -1

    def snapshot(self) -> Dict[str, int]:
        with self._lock:
            return {
                "connections": len(self._connections),
                "generation": self._generation,
            }


class BoundedExecutor:
    def __init__(self, max_workers: int, max_pending: int, prefix: str) -> None:
        self._max_workers = max_workers
        self._max_pending = max(max_workers, max_pending)
        self._prefix = prefix
        self._lock = threading.RLock()
        self._slots = threading.BoundedSemaphore(self._max_pending)
        self._executor: Optional[ThreadPoolExecutor] = None
        self._active: Dict[str, Future] = {}
        self._submitted = 0
        self._completed = 0
        self._reused = 0

    def start(self) -> None:
        with self._lock:
            if self._executor is None:
                self._executor = ThreadPoolExecutor(
                    max_workers=self._max_workers,
                    thread_name_prefix=self._prefix,
                )

    def submit(
        self,
        fn: Callable[..., object],
        *args: object,
        task_key: Optional[str] = None,
        **kwargs: object,
    ) -> Future:
        if _SHUTDOWN_EVENT.is_set():
            raise RuntimeError("plugin shutting down")
        while not self._slots.acquire(timeout=0.25):
            if _SHUTDOWN_EVENT.is_set():
                raise RuntimeError("plugin shutting down")
        try:
            with self._lock:
                if task_key:
                    active = self._active.get(task_key)
                    if active is not None and not active.done():
                        self._reused += 1
                        self._slots.release()
                        return active
                self.start()
                executor = self._executor
                if executor is None:
                    raise RuntimeError("background executor is unavailable")
                future = executor.submit(fn, *args, **kwargs)
                self._submitted += 1
                if task_key:
                    self._active[task_key] = future
        except Exception:
            self._slots.release()
            raise

        def _done(completed: Future) -> None:
            with self._lock:
                self._completed += 1
                if task_key and self._active.get(task_key) is completed:
                    self._active.pop(task_key, None)
            self._slots.release()

        future.add_done_callback(_done)
        return future

    def stop(self, wait: bool = True) -> None:
        with self._lock:
            executor = self._executor
            self._executor = None
            self._active.clear()
        if executor is None:
            return
        try:
            executor.shutdown(wait=wait, cancel_futures=True)
        except TypeError:
            executor.shutdown(wait=wait)

    def snapshot(self) -> Dict[str, int]:
        with self._lock:
            return {
                "submitted": self._submitted,
                "completed": self._completed,
                "active": sum(1 for future in self._active.values() if not future.done()),
                "reused": self._reused,
                "max_workers": self._max_workers,
                "max_pending": self._max_pending,
            }


class BackgroundTaskScheduler:
    def __init__(self) -> None:
        self.work = BoundedExecutor(8, 128, "fzr_worker")
        self.io = BoundedExecutor(8, 128, "fzr_io")

    def start(self) -> None:
        self.work.start()
        self.io.start()

    def stop(self, wait: bool = True) -> None:
        self.work.stop(wait=wait)
        self.io.stop(wait=wait)

    def snapshot(self) -> Dict[str, Dict[str, int]]:
        return {
            "work": self.work.snapshot(),
            "io": self.io.snapshot(),
        }


class TimedValueCache:
    def __init__(self, ttl: float, max_entries: int) -> None:
        self._ttl = max(1.0, ttl)
        self._max_entries = max(1, max_entries)
        self._lock = threading.RLock()
        self._values: Dict[str, Tuple[float, object]] = {}

    def get(self, key: str) -> Optional[object]:
        now = time.monotonic()
        with self._lock:
            item = self._values.get(key)
            if item is None:
                return None
            expires_at, value = item
            if expires_at <= now:
                self._values.pop(key, None)
                return None
            return value

    def put(self, key: str, value: object) -> None:
        now = time.monotonic()
        with self._lock:
            if len(self._values) >= self._max_entries:
                oldest = min(self._values, key=lambda item: self._values[item][0])
                self._values.pop(oldest, None)
            self._values[key] = (now + self._ttl, value)

    def clear(self) -> None:
        with self._lock:
            self._values.clear()

    def snapshot(self) -> Dict[str, int]:
        now = time.monotonic()
        with self._lock:
            expired = [
                key for key, (expires_at, _value) in self._values.items()
                if expires_at <= now
            ]
            for key in expired:
                self._values.pop(key, None)
            return {"entries": len(self._values)}

