        assert _catalog_prices == {
            "catalog-one": "1.25",
            "catalog-two": "2.50",
        }
        assert _catalog_api.calls == [("giftcards", "shared")]
        assert _fetch_current_prices_usd(
            _catalog_api, _catalog_mappings) == _catalog_prices
        assert _catalog_api.calls == [("giftcards", "shared")]
        _PRICE_CATALOG_CACHE.clear()
