        class _RetryViewingCardinal(_ViewingAutoreplyCardinal):
            def __init__(self) -> None:
                super().__init__()
                self.attempts = 0

            def send_message(
                self,
                chat_id: int | str,
                text: str,
                username: Optional[str],
                watermark: bool = True,
            ) -> None:
                self.attempts += 1
                if self.attempts == 1:
                    raise RuntimeError("smoke send failure")
                super().send_message(chat_id, text, username, watermark)

